package de.lazytv.pro.playlist;import de.lazytv.pro.activation.ActivationGuard;import android.app.Activity;import android.content.Intent;import android.net.Uri;import android.os.Bundle;import android.provider.OpenableColumns;import android.database.Cursor;import android.view.View;import android.widget.*;import java.util.UUID;import de.lazytv.pro.R;
public class PlaylistEditorActivity extends Activity {public static final String EXTRA_ID="playlist_id";private static final int PICK_M3U=7001;private PlaylistStorage storage;private Playlist current;private Spinner type;private EditText name,url,user,pass,mac;private View urlRow,fileRow,xtreamFields,stalkerFields;private TextView fileName;private Uri selectedFile;@Override protected void onCreate(Bundle b){super.onCreate(b);if(!ActivationGuard.enforce(this))return;setContentView(R.layout.activity_playlist_editor);storage=new PlaylistStorage(this);bind();setupType();String id=getIntent().getStringExtra(EXTRA_ID);if(id!=null){current=storage.get(id);if(current!=null)fill(current);}else{String preset=getIntent().getStringExtra("preset_type");if("M3U".equals(preset))type.setSelection(0);else if("XTREAM".equals(preset))type.setSelection(2);else if("STALKER".equals(preset))type.setSelection(3);}findViewById(R.id.pick_file).setOnClickListener(v->pickFile());findViewById(R.id.save_playlist).setOnClickListener(v->save());}private void bind(){type=findViewById(R.id.type_spinner);name=findViewById(R.id.input_name);url=findViewById(R.id.input_url);user=findViewById(R.id.input_username);pass=findViewById(R.id.input_password);mac=findViewById(R.id.input_mac);urlRow=findViewById(R.id.url_row);fileRow=findViewById(R.id.file_row);xtreamFields=findViewById(R.id.xtream_fields);stalkerFields=findViewById(R.id.stalker_fields);fileName=findViewById(R.id.file_name);}private void setupType(){String[] labels={"M3U URL","M3U file lokal","Xtream Codes","Stalker / Portal"};type.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels));type.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int pos,long id){renderType();}public void onNothingSelected(AdapterView<?> p){}});}private PlaylistType selectedType(){switch(type.getSelectedItemPosition()){case 1:return PlaylistType.M3U_FILE;case 2:return PlaylistType.XTREAM_CODES;case 3:return PlaylistType.STALKER_PORTAL;default:return PlaylistType.M3U_URL;}}private void renderType(){PlaylistType t=selectedType();fileRow.setVisibility(t==PlaylistType.M3U_FILE?View.VISIBLE:View.GONE);urlRow.setVisibility(t==PlaylistType.M3U_FILE?View.GONE:View.VISIBLE);xtreamFields.setVisibility(t==PlaylistType.XTREAM_CODES?View.VISIBLE:View.GONE);stalkerFields.setVisibility(t==PlaylistType.STALKER_PORTAL?View.VISIBLE:View.GONE);}private void fill(Playlist p){name.setText(p.getName());url.setText(p.getUrl());user.setText(p.getUsername());pass.setText(p.getPassword());mac.setText(p.getMacAddress());int pos=p.getType()==PlaylistType.M3U_FILE?1:p.getType()==PlaylistType.XTREAM_CODES?2:p.getType()==PlaylistType.STALKER_PORTAL?3:0;type.setSelection(pos);if(p.getType()==PlaylistType.M3U_FILE)fileName.setText(p.getUrl());}private void pickFile(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"audio/x-mpegurl","application/vnd.apple.mpegurl","text/plain","application/octet-stream"});startActivityForResult(i,PICK_M3U);}@Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==PICK_M3U&&result==RESULT_OK&&data!=null&&data.getData()!=null){selectedFile=data.getData();try{int flags=data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);getContentResolver().takePersistableUriPermission(selectedFile,flags&Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}url.setText(selectedFile.toString());fileName.setText(displayName(selectedFile));}}private String displayName(Uri u){String n=u.getLastPathSegment();try(Cursor c=getContentResolver().query(u,null,null,null,null)){if(c!=null&&c.moveToFirst()){int i=c.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(i>=0)n=c.getString(i);}}catch(Exception ignored){}return n==null?"M3U file":n;}private void save(){PlaylistType t=selectedType();String id=current==null?UUID.randomUUID().toString():current.getId();String endpoint=url.getText().toString().trim().replace("&amp;","&");Playlist p=new Playlist(id,name.getText().toString().trim(),t,endpoint,user.getText().toString().trim(),pass.getText().toString(),mac.getText().toString().trim(),System.currentTimeMillis());String err=PlaylistValidator.validate(p);if(err!=null){Toast.makeText(this,err,Toast.LENGTH_LONG).show();return;}storage.save(p);storage.setActive(p.getId());Toast.makeText(this,"U ruajt. Katalogu ngarkohet kur hap rubrikën.",Toast.LENGTH_SHORT).show();Intent home=new Intent(this,de.lazytv.pro.MainActivity.class);home.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);startActivity(home);finish();}}
